changeSet.sql:
DO $$ BEGIN IF EXISTS ( SELECT 1 FROM message m WHERE m.type IS NULL OR m.type NOT IN ('HUMAN', 'ASSISTANT', 'SYSTEM') ) THEN RAISE EXCEPTION 'Cannot migrate messages with an unsupported message role'; END IF;
IF EXISTS ( SELECT 1 FROM message m WHERE m.type IN ('HUMAN', 'ASSISTANT', 'SYSTEM') AND NOT EXISTS ( SELECT 1 FROM chat c WHERE c.guid = m.chat_id AND c.tenant_id = m.tenant_id ) ) THEN RAISE EXCEPTION 'Cannot migrate messages with missing or mismatched chat ownership'; END IF;
IF EXISTS ( SELECT 1 FROM message m JOIN conversation_entry e ON e.chat_id = m.chat_id AND e.tenant_id = m.tenant_id AND CASE WHEN e.type = 'TEXT' THEN e.message_type ELSE e.type END = m.type AND e.text IS NOT DISTINCT FROM m.text AND e.user_id IS NOT DISTINCT FROM m.user_id AND e.creationuser IS NOT DISTINCT FROM m.creationuser WHERE m.type IN ('HUMAN', 'ASSISTANT', 'SYSTEM') AND (m.creationdate IS NULL OR COALESCE(e.modificationdate, e.creationdate) IS NULL) ) THEN RAISE EXCEPTION 'Cannot distinguish legacy message mirrors with null timestamps'; END IF;
IF EXISTS ( SELECT 1 FROM message m JOIN conversation_entry e ON e.chat_id = m.chat_id AND e.tenant_id = m.tenant_id AND e.type = m.type AND e.text IS NOT DISTINCT FROM m.text AND COALESCE(e.modificationdate, e.creationdate) BETWEEN m.creationdate - INTERVAL '1 second' AND m.creationdate + INTERVAL '1 second' WHERE m.type IN ('HUMAN', 'ASSISTANT') AND e.status IN ('COMPLETED', 'INTERRUPTED') AND (e.user_id IS DISTINCT FROM m.user_id OR e.creationuser IS DISTINCT FROM m.creationuser) ) THEN RAISE EXCEPTION 'Cannot distinguish potential voice mirrors with mismatched ownership metadata'; END IF;
IF EXISTS ( SELECT m.guid FROM message m JOIN conversation_entry e ON e.chat_id = m.chat_id AND e.tenant_id = m.tenant_id AND CASE WHEN e.type = 'TEXT' THEN e.message_type ELSE e.type END = m.type AND e.text IS NOT DISTINCT FROM m.text AND e.user_id IS NOT DISTINCT FROM m.user_id AND e.creationuser IS NOT DISTINCT FROM m.creationuser AND COALESCE(e.modificationdate, e.creationdate) BETWEEN m.creationdate - INTERVAL '1 second' AND m.creationdate + INTERVAL '1 second' WHERE m.type IN ('HUMAN', 'ASSISTANT', 'SYSTEM') GROUP BY m.guid HAVING COUNT(*) > 1 ) THEN RAISE EXCEPTION 'Cannot distinguish multiple matching conversation entries for a legacy message'; END IF;
IF EXISTS ( SELECT 1 FROM message m JOIN conversation_entry e ON e.chat_id = m.chat_id AND e.tenant_id = m.tenant_id WHERE m.type IN ('HUMAN', 'ASSISTANT', 'SYSTEM') AND e.status IN ('COMPLETED', 'INTERRUPTED') AND NOT EXISTS ( SELECT 1 FROM conversation_entry converted WHERE converted.chat_id = m.chat_id AND converted.tenant_id = m.tenant_id AND converted.idempotency_key = 'legacy-message:' || m.guid ) AND m.creationdate IS NOT NULL AND ( COALESCE(e.modificationdate, e.creationdate) IS NULL OR m.creationdate < COALESCE(e.modificationdate, e.creationdate) OR ( m.creationdate = COALESCE(e.modificationdate, e.creationdate) AND m.guid < e.guid ) ) AND NOT EXISTS ( SELECT 1 FROM conversation_entry mirror WHERE mirror.chat_id = m.chat_id AND mirror.tenant_id = m.tenant_id AND mirror.type IN ('HUMAN', 'ASSISTANT') AND mirror.type = m.type AND mirror.text IS NOT DISTINCT FROM m.text AND mirror.user_id IS NOT DISTINCT FROM m.user_id AND mirror.creationuser IS NOT DISTINCT FROM m.creationuser AND COALESCE(mirror.modificationdate, mirror.creationdate) BETWEEN m.creationdate - INTERVAL '1 second' AND m.creationdate + INTERVAL '1 second' ) ) THEN RAISE EXCEPTION 'Cannot preserve sequence order for legacy messages in a chat with existing entries'; END IF;
IF EXISTS ( SELECT 1 FROM message m JOIN conversation_entry e ON e.guid = m.guid WHERE m.type IN ('HUMAN', 'ASSISTANT', 'SYSTEM') AND e.idempotency_key <> 'legacy-message:' || m.guid ) THEN RAISE EXCEPTION 'Legacy message ID conflicts with a conversation entry ID'; END IF;
IF EXISTS ( SELECT 1 FROM message m WHERE LENGTH('legacy-message:' || m.guid) > 255 ) THEN RAISE EXCEPTION 'Legacy message ID is too long for a stable idempotency key'; END IF; END $$;
